INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Prototypen immer voll funktionsfähig?', 2, '[{"text": "Nein", "correct": true, "because": "Sie simulieren oft nur Teile"}, {"text": "Ja", "correct": false, "because": "Fokus liegt auf Validierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Prototyp?', 3, '[{"text": "Nutzerfeedback sammeln", "correct": true, "because": "Validierung ist zentral"}, {"text": "Endprodukt fertigstellen", "correct": false, "because": "Prototyp ist nicht final"}, {"text": "Design finalisieren", "correct": false, "because": "Das machen Mockups"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen einen Prototyp effektiv?', 5, '[{"text": "Interaktivität", "correct": true, "because": "Erlaubt Nutzertests"}, {"text": "Realistische Simulation", "correct": true, "because": "Spiegelt Nutzung wider"}, {"text": "Perf ambitiöse Grafik", "correct": false, "because": "Sekundär für Funktion"}, {"text": "Vollständige Datenbank", "correct": false, "because": "Nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Prototypen testen Funktionalität. b) Sie ersetzen das finale Produkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prototypen sind nicht das Endprodukt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Prototyp für Nutzertests?', 4, '[{"text": "Benutzerinteraktion", "correct": false, "because": "Kernmerkmal des Tests"}, {"text": "Funktionale Elemente", "correct": false, "because": "Wichtig für Feedback"}, {"text": "Perfekte Ästhetik", "correct": true, "because": "Fokus liegt auf Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Prototyp nur für Software gedacht ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Hardware oder Prozesse"}, {"text": "Ja", "correct": false, "because": "Anwendung ist breiter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich für einen interaktiven Prototyp?', 3, '[{"text": "Figma", "correct": true, "because": "Bietet Interaktivität"}, {"text": "Photoshop", "correct": false, "because": "Nur statische Designs"}, {"text": "Excel", "correct": false, "because": "Keine Prototyping-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Erstellung eines Prototypen?', 5, '[{"text": "Anforderungen definieren", "correct": true, "because": "Legt den Fokus fest"}, {"text": "Interaktionen einbauen", "correct": true, "because": "Macht ihn testbar"}, {"text": "Finale Datenbank anbinden", "correct": false, "because": "Zu früh im Prozess"}, {"text": "Code optimieren", "correct": false, "because": "Später im Entwicklungsprozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Prototypen sparen Entwicklungszeit. b) Sie sind teurer als das Endprodukt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sie reduzieren spätere Änderungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Prototyp für eine App unwichtig?', 4, '[{"text": "Navigationstest", "correct": false, "because": "Wichtig für Nutzererfahrung"}, {"text": "Grundfunktionen", "correct": false, "because": "Kern des Tests"}, {"text": "Endgültige Farbschemata", "correct": true, "because": "Später im Designprozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Dient ein Prototyp nur dem Designer?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Nutzer und Entwickler"}, {"text": "Ja", "correct": false, "because": "Breitere Zielgruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Prototypen gibt es?', 4, '[{"text": "Low-Fidelity", "correct": true, "because": "Einfache Skizzen"}, {"text": "High-Fidelity", "correct": true, "because": "Detailreiche Modelle"}, {"text": "Statische Designs", "correct": false, "because": "Das sind Mockups"}, {"text": "Code-basierte", "correct": false, "because": "Später im Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Prototypen nur für große Projekte sinnvoll sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Universell einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Prototyp für eine Webseite?', 3, '[{"text": "Klickbare Links", "correct": true, "because": "Testet Navigation"}, {"text": "Finale Inhalte", "correct": false, "because": "Später hinzufügen"}, {"text": "SEO-Optimierung", "correct": false, "because": "Nicht im Prototyping"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Prototypen brauchen Nutzertests. b) Sie sind ohne Feedback nutzlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Feedback ist hilfreich, aber nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist übertrieben"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente teste ich mit einem Prototyp?', 5, '[{"text": "Benutzerfreundlichkeit", "correct": true, "because": "Kernziel der Validierung"}, {"text": "Workflows", "correct": true, "because": "Prüft Abläufe"}, {"text": "Serverlast", "correct": false, "because": "Später im Prozess"}, {"text": "Datenintegrität", "correct": false, "because": "Nicht primär im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Prototyp für ein Spiel?', 3, '[{"text": "Spielmechaniken", "correct": false, "because": "Kern des Tests"}, {"text": "Interaktionen", "correct": false, "because": "Wichtig für Feedback"}, {"text": "Finale Grafiken", "correct": true, "because": "Später im Design"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit der Validierung? Ist sie nur für Kunden?', 3, '[{"text": "Nein", "correct": true, "because": "Auch für Team und Stakeholder"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Prototyp teuer sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Low-Fidelity ist günstig"}, {"text": "Ja", "correct": false, "because": "Kosten variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein Prototyp im Entwicklungsprozess?', 4, '[{"text": "Ideen testen", "correct": true, "because": "Frühe Validierung"}, {"text": "Fehler finden", "correct": true, "because": "Vor der Entwicklung"}, {"text": "Endprodukt liefern", "correct": false, "because": "Nur ein Schritt"}]');
